    this.ring.position.y = 0.42;

    this.group = new THREE.Group();
    this.group.add(this.body, this.ring);
    this.group.visible = false;
    scene.add(this.group);

    this.trail = new MotionTrail({ color: 0xffd24a, segments: 14, width: 0.5, fade: 0.5 });
    this.trail.addTo(scene);

    tracker.track(bodyGeo);
    tracker.track(bodyMat);
    tracker.track(ringGeo);
    tracker.track(ringMat);
    tracker.track(this.trail);
  }

  spawn(rng, wave) {
    this.active = true;
    this.score = this._pickScore(rng);
    const fromLeft = rng() < 0.5;
    this.x = fromLeft ? -13 : 13;
    this.vx = (fromLeft ? 1 : -1) * (CONFIG.UFO_SPEED + 1.5 * (wave - 1));
    this.group.visible = true;
    this.trail.clear();
    this._place();
  }

  _pickScore(rng) {
    const table = CONFIG.UFO_SCORES;
    let total = 0;
    for (const e of table) total += e.weight;
    let r = rng() * total;
    for (const e of table) {
      r -= e.weight;
      if (r <= 0) return e.value;
    }
    return table[table.length - 1].value;
  }

  _place() {
    this.group.position.set(this.x, 0.6, this.z);
    this._pos.x = this.x;
    this._pos.z = this.z;
  }

  update(dt) {
    if (!this.active) return;
    this.x += this.vx * dt;
    this._ringAngle += dt * 2.2;
    this.ring.rotation.z = this._ringAngle;
    if (this.x < -14 || this.x > 14) {
      this.active = false;
      this.group.visible = false;
      this.trail.clear();
      return;
    }
    this._place();
    this.trail.update(this._pos, dt);
  }

  get bounds() {
    return {
      minX: this.x - 1.5, maxX: this.x + 1.5,
      minZ: this.z - 0.8, maxZ: this.z + 0.8,
    };
  }

  deactivate() {
    this.active = false;
    this.group.visible = false;
    this.trail.clear();
  }

  dispose(scene) {
    this.trail.dispose(scene);
    if (this.group.parent) scene.remove(this.group);
    this.body.geometry.dispose();
    this.body.material.dispose();
    this.ring.geometry.dispose();
    this.ring.material.dispose();
  }
}

import { CONFIG } from '../config.js';

const HI_KEY = 'neon_invaders_hi';

/**
 * ScoreSystem — score, combo multiplier, extra lives, hi-score persistence.
 */
export class ScoreSystem {
  constructor() {
    this.score = 0;
    this.hiScore = this._loadHi();
    this.combo = 0;
    this.multiplier = 1;
    this.lives = CONFIG.START_LIVES;
    this.extraLifeAt = CONFIG.EXTRA_LIFE_FIRST;
    this.extraLifeStep = CONFIG.EXTRA_LIFE_STEP;
    this.wave = 1;
  }

  _loadHi() {
    try {
      const v = parseInt(localStorage.getItem(HI_KEY), 10);
      return Number.isFinite(v) && v > 0 ? v : 0;
    } catch {
      return 0;
    }
  }

  _saveHi() {
    try {
      localStorage.setItem(HI_KEY, String(this.hiScore));
    } catch {
      /* storage unavailable — ignore */
    }
  }

  reset() {
    this.score = 0;
    this.combo = 0;
    this.multiplier = 1;
    this.lives = CONFIG.START_LIVES;
    this.extraLifeAt = CONFIG.EXTRA_LIFE_FIRST;
    this.wave = 1;
  }

  /**
   * Add a kill. Returns { gained, multiplier, extraLife }.
   */
  addKill(baseValue) {
    this.combo++;
    this.multiplier = Math.min(CONFIG.COMBO.max, 1 + Math.floor(this.combo / 4) * 0.25);
    const gained = Math.round(baseValue * this.multiplier);
    this.score += gained;
    if (this.score > this.hiScore) {
      this.hiScore = this.score;
      this._saveHi();
    }
    let extraLife = false;
    if (this.score >= this.extraLifeAt) {
      this.lives = Math.min(9, this.lives + 1);
      this.extraLifeAt += this.extraLifeStep;
      extraLife = true;
    }
    return { gained, multiplier: this.multiplier, extraLife };
  }

  /**
   * Add a flat score (e.g. the UFO) without touching the combo.
   * @returns {number} the amount added
   */
  addScore(value) {
    this.score += value;
    if (this.score > this.hiScore) {
      this.hiScore = this.score;
      this._saveHi();
    }
    return value;
  }

  /** A missed bullet (left field / hit bunker) resets the combo. */
  miss() {
    this.combo = 0;
    this.multiplier = 1;
  }

  /**
   * Player was hit. Returns true if this was the final life.
   */
  loseLife() {
    this.lives--;
    this.combo = 0;
    this.multiplier = 1;
    return this.lives <= 0;
  }

  nextWave() {
    this.wave++;
  }
}

import { createRng } from '@shared/math/rng.js';
import { CONFIG } from '../config.js';

/**
 * SpawnerSystem — owns all timed spawning: invader bombs and the UFO.
 * Seeded RNG (createRng) for reproducible waves.
 *
 * `update()` returns a single event object (or null):
 *   { type: 'bomb', x, z, speed }   — spawn a bomb at (x, z)
 *   { type: 'ufo' }                 — spawn the UFO (it picks its own score)
 */
export class SpawnerSystem {
  constructor(seed = 0x51a7) {
    this.rng = createRng(seed);
    this.bombTimer = 2.0;
    this.ufoTimer = 14;
  }

  reset(seed) {
    this.rng = createRng(seed >>> 0);
    this.bombTimer = 2.0;
    this.ufoTimer = 12 + this.rng.next() * 8;
  }

  /**
   * Advance timers.
   * @param {number} dt
   * @param {object} formation — InvaderFormation
   * @param {number} wave
   * @returns {object|null}
   */
  update(dt, formation, wave) {
    if (formation.liveCount === 0) return null;

    // Bomb timer.
    this.bombTimer -= dt;
    if (this.bombTimer <= 0) {
      const t = 1 - formation.liveCount / CONFIG.INVADERS.total;
      const interval =
        (CONFIG.BOMBS.intervalMax -
          (CONFIG.BOMBS.intervalMax - CONFIG.BOMBS.intervalMin) * t) /
        (1 + 0.1 * (wave - 1));
      this.bombTimer = interval * (0.7 + this.rng.next() * 0.6);

      const idx = this._pickBottomWeighted(formation);
      if (idx >= 0) {
        const p = formation.invaderXZ(idx);
        const speed =
          CONFIG.BOMBS.speedMin +
          (CONFIG.BOMBS.speedMax - CONFIG.BOMBS.speedMin) * t +
          1.5 * (wave - 1);
        return { type: 'bomb', x: p.x, z: p.z, speed };
      }
    }

    // UFO timer.
    this.ufoTimer -= dt;
    if (this.ufoTimer <= 0) {
      this.ufoTimer = 12 + this.rng.next() * 8;
      return { type: 'ufo' };
    }

    return null;
  }

  /** Weighted pick favoring the bottom rows (classic behavior). */
  _pickBottomWeighted(formation) {
    const weights = CONFIG.INVADERS.BOMB_ROW_WEIGHTS; // row 0 (top) → row 4 (bottom)
    const live = formation.liveList;
    if (live.length === 0) return -1;
    const pool = [];
    for (const idx of live) {
      const row = formation.invaderType(idx);
      const w = weights[row] ?? 1;
      for (let i = 0; i < w; i++) pool.push(idx);
    }
    return pool[Math.floor(this.rng.next() * pool.length)] ?? -1;
  }
}

// Deterministic RNG utilities (mulberry32) + weighted selection.

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Returns a bound API over a seeded generator.
export function createRng(seed = 1337) {
  const next = mulberry32(seed);
  return {
    next,
    range(min, max) {
      return min + (max - min) * next();
    },
    int(min, max) {
      // inclusive on both ends
      return Math.floor(min + (max - min + 1) * next());
    },
    pick(arr) {
      return arr[Math.floor(next() * arr.length)];
    },
    bool(p = 0.5) {
      return next() < p;
    },
    // items: [{ weight, value }] — returns value
    weighted(items) {
      let total = 0;
      for (const it of items) total += it.weight;
      let r = next() * total;
      for (const it of items) {
        r -= it.weight;
        if (r <= 0) return it.value;
      }
      return items[items.length - 1].value;
    },
  };
}

// Piecewise-linear interpolation over a sorted table.
// table: [[x0, y0], [x1, y1], ...] — x ascending.
export function lerpTable(table, x) {
  if (x <= table[0][0]) return table[0][1];
  const last = table[table.length - 1];
  if (x >= last[0]) return last[1];
  for (let i = 1; i < table.length; i++) {
    if (x <= table[i][0]) {
      const [x0, y0] = table[i - 1];
      const [x1, y1] = table[i];
      const t = (x - x0) / (x1 - x0);
      return y0 + (y1 - y0) * t;
    }
  }
  return last[1];
}

