export class HUD {
  constructor(container) {
    this.root = GlassUI.root(container);
    this.bar = document.createElement('div');
    this.bar.className = 'glass-hud';
    this.root.appendChild(this.bar);

    // Left: score + hi-score.
    this.scoreEl = this._block('SCORE', '0');
    this.hiEl = this._block('HI-SCORE', '0');
    this.bar.appendChild(this.scoreEl);
    this.bar.appendChild(this.hiEl);

    // Center: wave + combo.
    const center = document.createElement('div');
    center.className = 'hud-center';
    this.waveEl = this._block('WAVE', '1');
    const comboWrap = document.createElement('div');
    comboWrap.className = 'combo-meter';
    this.comboFill = document.createElement('div');
    this.comboFill.className = 'combo-fill';
    comboWrap.appendChild(this.comboFill);
    this.comboLabel = document.createElement('div');
    this.comboLabel.className = 'hud-label';
    this.comboLabel.textContent = 'COMBO ×1';
    center.append(this.waveEl, comboWrap, this.comboLabel);
    this.bar.appendChild(center);

    // Right: lives + power tags.
    this.livesEl = this._block('LIVES', '3');
    this.powerWrap = document.createElement('div');
    this.powerWrap.className = 'power-tags';
    this.bar.appendChild(this.livesEl);
    this.bar.appendChild(this.powerWrap);

    // Damage flash overlay.
    this.flash = GlassUI.flashOverlay(this.root);
  }

  _block(label, value) {
    const el = GlassUI.hudBlock(label, value);
    return el;
  }

  set({ score, hiScore, lives, wave, combo, powerTimers }) {
    this._setVal(this.scoreEl, score);
    this._setVal(this.hiEl, hiScore);
    this._setVal(this.livesEl, lives);
    this._setVal(this.waveEl, wave);
    // combo meter
    const mult = combo || 1;
    const frac = (mult - 1) / 3; // 1 → 0, 4 → 1
    this.comboFill.style.width = `${Math.max(0, Math.min(1, frac)) * 100}%`;
    this.comboLabel.textContent = `COMBO ×${mult.toFixed(2).replace(/\.?0+$/, '')}`;
    // power tags
    this._renderPowerTags(powerTimers);
  }

  _setVal(blockEl, value) {
    const v = blockEl.querySelector('.hud-value');
    if (v && v.textContent !== String(value)) v.textContent = String(value);
  }

  _renderPowerTags(powerTimers) {
    if (!powerTimers) return;
    const active = Object.entries(powerTimers).filter(([, t]) => t > 0);
    // Rebuild tags (cheap; only a few).
    this.powerWrap.textContent = '';
    for (const [type, t] of active) {
      const tag = document.createElement('div');
      tag.className = 'power-tag';
      tag.textContent = `${type} ${t.toFixed(1)}s`;
      this.powerWrap.appendChild(tag);
    }
  }

  dispose() {
    if (this.root && this.root.parentNode) this.root.parentNode.removeChild(this.root);
    this.root = null;
  }
}
